sketches.source:
setcpm(150/4)

// One break, mangled differently almost every bar
const brk = s("bd ~ [~ bd] ~ sd ~ bd sd, hh*16")
drums: brk.someCyclesBy(.5, x => x.scramble(16)).sometimesBy(.25, x => x.ply("<2 3 4>"))
  .chunk(4, x => x.hurry(2)).crush("<16 8 4 6>").seed("gremlin").gain(.6)

// A bass ring-modulated into a gargling metal lump
bass: note("c2 ~ c2 eb2 ~ c2 gb2 ~").s("sawtooth").ringmod(sine.range(30, 400).slow(4)).ringmix(.6)
  .lpf(1200).decay(.15).sustain(.3).release(.05).gain(.4)

// Clicks at random speeds that run backwards in random bars
clicks: s("click*16?0.5").speed(rand.range(.5, 3)).someCycles(x => x.rev())
  .pan(rand).seed("sprocket").gain(.15)

// A frequency-shifted bell: every partial moves by the same hertz, so no key survives
bells: note("<c5 gb5 a4 eb5>").s("sine").fm(4).fmh(1.41).fshift("<0 37 -113 250>")
  .decay(.4).sustain(0).delay(.3).delaytime(3/16).delayfeedback(.5).gain(.14)

setcpm(96/4)

// A loud sine through chebyN comes out as its Nth harmonic:
// one tune, jumping to the 2nd, 3rd, 5th and 7th harmonic bar by bar
lead: n("0 2 4 7 4 2 0 -1").scale("A:minor").transpose(12)
  .s("sine").curve("<cheby2 cheby3 cheby5 cheby7>").drive(18)
  .decay(.2).sustain(.4).release(.1).lpf(6000).gain(.18)

// A bass folded over on itself, harder every bar, through a stack cabinet
bass: note("<a1 a1 f1 g1>").struct("x ~ x x ~ x ~ x").s("sine")
  .curve("fold").drive(sine.range(4, 22).slow(4)).bias(.2)
  .decay(.2).sustain(.4).release(.05).cab("stack").gain(.35)

// Drums through a full-wave rectifier, half wet
drums: s("bd ~ bd ~, ~ sd ~ sd, hh*8").curve("rect").drive(8).curvemix(.5).gain(.45)

setcpm(220/4)

// One function for the whole band: on the last bar of every eight, everything rushes twice as fast
const polka = (x) => x.lastOf(8, y => y.hurry(2))

// Accordion oom-pah: two reeds tuned apart, through an a vowel
oompah: note("<[c2 [e3,g3] g1 [e3,g3]] [g1 [d3,f3,b3] d2 [d3,f3,b3]]>")
  .s("sawtooth").timbre("reed").unison(2).detune(16).vowel("a").lpf(2000)
  .decay(.15).sustain(.3).release(.05).polka().gain(.3)

// The tune, far too cheerful
tune: note("<[e5 g5 e5 c5] [d5 f5 d5 b4] [e5 g5 c6 g5] [d5@2 c5@2]>")
  .s("sawtooth").timbre("reed").vowel("e").lpf(3000).attack(.01).sustain(.6).release(.05)
  .polka().gain(.22)

drums: s("bd sd bd sd, hh*8").polka().gain(.45)

// Meanwhile, the sky is falling: an air-raid siren gliding up and down
siren: freq(sine.range(500, 1100).slow(2).segment(16)).s("sine").mono(1).glide(.12)
  .attack(.01).sustain(1).release(.05).gain(.06)

// And a rumble that darkens and swells over eight bars
rumble: s("brown*4").lpf(saw.range(100, 1200).slow(8)).gain(saw.range(.02, .2).slow(8))
  .attack(.05).release(.1)

setcpm(120/4)

// The swarm: one bee circles once a bar, one the other way every two bars, one darts at random
bee1: s("insect*8").azimuth(saw.range(-180, 180)).elevation(20).distance(1).posglide(.1).gain(.18)
bee2: s("insect*8").azimuth(isaw.range(-180, 180).slow(2)).elevation(-10).distance(1.5).posglide(.1).gain(.14)
bee3: s("insect*16").azimuth(rand.range(-180, 180)).elevation(rand.range(-40, 60))
  .distance(.7).posglide(.05).seed("sting").gain(.1)

// Hats lean right, and a seeded coin flip sends some of them to the left
hats: s("hh*16").hpf(7000).ild(10).earswap(irand(2).segment(16)).seed("hop").gain(.25)

// The phase between the ears turns half a time, once, twice, then almost three times a second
drone: note("[e2,b2]").s("sawtooth").irate("<.5 1 2 2.9>").lpf(800)
  .attack(1).sustain(1).release(1).gain(.18)

// The kick: the only thing left in the middle of your head
kick: s("bd*4").shape(.2).gain(.6)

setcpm(110/4)

// A saw bass with something to say: talk puts a syllable track on it
bass: note("c2 c2 eb2 c2 g1 c2 bb1 c2").s("sawtooth")
  .syl("<[wa wa wo wi] [ya ya yo yu] [ba ba bo bi] [na na no neng]>").talk(1)
  .lpf(2400).decay(.2).sustain(.4).gain(.35)

// A crunchy, swung breakfast beat
drums: s("bd ~ [~ bd] ~, ~ sd ~ sd, hh*8").swing(4).crush(10).gain(.45)

// The radio mutters in the corner
radio: s("whisper*8?0.5").syl("<sha ko ta ri>").crush(4).hpf(1000).seed("static").pan(.8).gain(.14)

// The kettle works up to a whistle, and the toaster pops
kettle: note("<~ ~ ~ c7>").s("sine").vib(8).vibdepth(.3).attack(1).sustain(1).release(.5).gain(.05)
pop: s("<~ ~ ~ [~ ~ ~ click]>").speed(.5).gain(.5)

// The announcement: toast is ready
robot: note("<c4 eb4 g4 bb4>").s("voice").syl("<toast is re_a dee>").voicetype("bass")
  .spectral("robot").samount(.7).mono(1).vglide(.04).gain(.26)
